export type MaterialStatus = 'pending' | 'ready' | 'processing' | 'failed' | 'cancelled'

export interface CourseAnalysis {
  title: string
  summary: string
  learning_path: string[]
  key_concepts: string[]
  review_questions: string[]
  /** Instructor-style tiered lecture generated by the backend AI. */
  knowledge_map?: KnowledgeNode[]
}

export type KnowledgeTier = 'prereq' | 'core' | 'advanced'

export interface KnowledgeNode {
  id: string
  title: string
  tier: KnowledgeTier
  summary: string
  /** Markdown content (GFM + LaTeX via $...$ and $$...$$). */
  content: string
}

export const TIER_META: Record<KnowledgeTier, { label: string; eyebrow: string; order: number }> = {
  prereq: { label: '前置知识', eyebrow: 'PREREQUISITE', order: 0 },
  core: { label: '核心知识点', eyebrow: 'CORE · 按讲课逻辑', order: 1 },
  advanced: { label: '进阶应用', eyebrow: 'ADVANCED', order: 2 },
}

function cleanStepText(value: string) {
  return value.replace(/^\s*(?:第?\d+[.、)）:]|[-*•])\s*/, '').replace(/\s+/g, ' ').trim()
}

function splitStep(value: string) {
  const clean = cleanStepText(value)
  const separator = clean.search(/[：:。；;]/)
  return {
    title: (separator > 0 ? clean.slice(0, separator) : clean).trim(),
    detail: (separator > 0 ? clean.slice(separator + 1) : '').trim(),
  }
}

// Source-file names like add.h / main.cpp — wrapped in backticks. Document
// extensions (pdf/docx/…) are deliberately excluded so material names stay plain.
const CODE_FILE_RE = /\b[A-Za-z_][\w-]*\.(?:h|hpp|hh|hxx|cpp|cc|cxx|c|py|js|mjs|cjs|ts|tsx|jsx|java|go|rs|rb|php|sh|bash|bat|ps1|sql|json|ya?ml|toml|ini|cfg|xml|html|css|scss|vue|kt|swift|mm)\b/g
// Math-like runs: a term (optionally sub/superscripted) joined by operators, or a
// single braced sub/superscript. Only wrapped when it actually carries _, ^ or =.
const MATH_RE = /[A-Za-z0-9]+(?:[_^]\{[^}]+\}|[_^][A-Za-z0-9])?(?:\s*[=+\-*/^]\s*[A-Za-z0-9]+(?:[_^]\{[^}]+\}|[_^][A-Za-z0-9])?)+|[A-Za-z0-9]+[_^]\{[^}]+\}/g

/**
 * Backend analysis text is plain prose: file names and formulas arrive without
 * Markdown/LaTeX delimiters, so they render as literal text. This adds them
 * heuristically — `code` for source files, $…$ for sub/superscript formulas —
 * so every study page renders consistently. Text already containing code or
 * math delimiters is left untouched.
 */
export function normalizeMarkdown(raw: string): string {
  if (!raw) return raw
  if (/\$|```|`[^`]+`/.test(raw)) return raw
  let text = raw.replace(CODE_FILE_RE, (match) => `\`${match}\``)
  text = text.replace(MATH_RE, (match) => (/[_^=]/.test(match) ? `$${match}$` : match))
  return text
}

/**
 * Build a tiered knowledge map from a backend analysis when the course has no
 * authored `knowledgeMap`. The ordered learning path is split into
 * 前置 / 核心 / 进阶, and each node gets its own focus, a distinct slice of the
 * key concepts and its matching review question — so no two nodes look alike.
 */
export function deriveKnowledgeMap(analysis: CourseAnalysis): KnowledgeNode[] {
  const steps = analysis.learning_path || []
  const total = steps.length
  if (!total) return []
  const edge = total <= 2 ? 0 : Math.max(1, Math.round(total * 0.2))
  const prereqEnd = edge
  const advancedStart = total - edge
  // Round-robin the concepts so every node owns a different, non-overlapping set.
  const buckets: string[][] = Array.from({ length: total }, () => [])
  ;(analysis.key_concepts || []).forEach((concept, index) => buckets[index % total].push(concept))
  return steps.map((rawStep, index) => {
    const { title, detail } = splitStep(rawStep)
    const tier: KnowledgeTier = index < prereqEnd ? 'prereq' : index >= advancedStart ? 'advanced' : 'core'
    const concepts = buckets[index]
    const question = analysis.review_questions?.[index]
    const summary = detail || concepts.slice(0, 2).join('、') || `第 ${index + 1} 个学习阶段`
    const parts: string[] = [`## ${title}`]
    if (index === 0 && analysis.summary) parts.push(normalizeMarkdown(analysis.summary))
    parts.push(`**本步聚焦**：${normalizeMarkdown(detail || title)}`)
    if (concepts.length) parts.push(`### 相关概念\n\n${concepts.map((concept) => `- ${normalizeMarkdown(concept)}`).join('\n')}`)
    if (question) parts.push(`### 自测\n\n> ${normalizeMarkdown(question)}`)
    parts.push(`> 本节内容由「${analysis.title}」的 AI 分析整理，可在右侧向 AI 讲师追问以展开更多细节。`)
    return { id: `analysis-${index}`, title, tier, summary, content: parts.join('\n\n') }
  })
}

export interface ProcessingJob {
  jobId: string
  materialIds: string[]
  progress: number
  stage: string
  message: string
  filesTotal?: number
  filesDone?: number
  currentFile?: string
  pagesTotal?: number
  pagesDone?: number
  startedAt?: number
}

export interface ExplorationNode {
  id: string
  title: string
  parentId: string
  question: string
}

export interface StudyMessage {
  id: string
  role: 'user' | 'assistant'
  content: string
  nodeId?: string
}

export interface Material {
  id: string
  name: string
  meta: string
  type: string
  status: MaterialStatus
  progress?: number
  error?: string
  previewUrl?: string
  pages?: number
}

export type SectionStatus = 'empty' | 'building' | 'ready' | 'failed'

/**
 * A 小节 (section): the unit a user actually builds and studies. Each section is
 * fully isolated — its own files, analysis, knowledge map, chat and mastery — so
 * sections never share or mix content.
 */
export interface Section {
  id: string
  title: string
  createdAt: number
  status: SectionStatus
  materials: Material[]
  analysis?: CourseAnalysis
  analysisJobId?: string
  knowledgeMap?: KnowledgeNode[]
  processingJob?: ProcessingJob
  explorationNodes?: ExplorationNode[]
  chatHistory?: StudyMessage[]
  mastery?: number
}

export interface Course {
  id: string
  title: string
  code: string
  description: string
  tags: string[]
  /** Aggregate (average of sections) — display only. */
  mastery: number
  updated: string
  accent: string
  sections: Section[]
}

export function createSection(title: string): Section {
  return { id: `section-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`, title: title.trim() || '新小节', createdAt: Date.now(), status: 'empty', materials: [] }
}

